MR.people["qing:suoetu"] = {
 "headline": "擒鳌拜的侍卫，幽死狱中的国舅",
 "lead": "索额图，赫舍里氏，满洲正黄旗，辅政大臣索尼第三子。他的侄女是康熙的孝诚皇后，皇后所生的胤礽后来被立为皇太子，索额图因此成了太子的外家、朝廷的外戚。康熙八年，他以侍卫身份在宫中替皇帝召集满洲少年，天天演习布库，把一场针对鳌拜的政变藏进了游戏里；鳌拜被擒，他第二年就入阁，授保和殿大学士。三藩之乱起，他主张慰留吴三桂，乱后又要处斩主张撤藩的大臣，被康熙一句「撤藩出自朕意」挡了回去；此后他转而调度诸军，扼守险要，节节策应，成为康熙朝事实上的参谋总长。康熙十九年，他被明珠排挤出内阁，以病辞职，改任内大臣兼议政大臣，后又调领侍卫内大臣，重掌宫廷宿卫。康熙二十八年，他率使团赴尼布楚，带一万兵丁为后盾，与俄使戈洛文反复争执，终以武力压出《尼布楚条约》。晚年他结党趋奉太子，议论国政，康熙四十二年以妄行议论国事被逮，不久死于狱中；康熙四十七年太子被废，其二子格尔芬、阿尔吉善同日问斩。他的一生有两个顶点：擒鳌拜与尼布楚；也有一个死结：外戚与储位绑得太紧。",
 "points": [
  "转折一：康熙八年助擒鳌拜，由侍卫入阁拜相，赫舍里氏从辅臣之家变成外戚重门。",
  "转折二：撤藩之争主张慰留，乱起后又请斩主撤者，被康熙驳回，转以军功立身。",
  "转折三：晚年结党东宫，康熙四十二年逮系幽死，太子被废后二子同日问斩。"
 ],
 "why": [
  {
   "q": "为什么索额图能从一名侍卫做到保和殿大学士？",
   "a": "因为康熙亲政之初最缺的是自己人。索尼已死，鳌拜专权，皇帝身边能用的只有满洲勋贵子弟里那些还没有党附的人。索额图是索尼第三子，家世足以压住场面；他辞掉吏部侍郎回宫当一等侍卫，替皇帝张罗那群练布库的少年，把政变办得不动声色。擒鳌拜之后，这份功劳没有第二个人分，入阁便是自然的酬庸。说到底，他的拜相不是靠资历排到的，是在最关键的一件事上站对了位置。",
   "basis": {
    "type": "book",
    "text": "《正说清朝十二帝》第五章 康熙帝玄烨"
   }
  }
 ],
 "gap": [
  "索额图在狱中的具体死因，底本只记「不久便死在牢里」，未载是病故还是处死。",
  "尼布楚谈判中他个人让步的具体分寸，底本只记帐中交锋与渡河布阵，未列逐条界址。"
 ],
 "quotes": []
};
