 "headline": "从翰林到赐死：两年走完的宠与罪",
 "lead": "年羹尧，汉军镶黄旗人，父年遐龄由笔帖式历升兵部主事、刑部郎中、河南道御史、工部侍郎、湖广巡抚，一门以文吏起家。他本人是康熙三十九年的进士，改庶吉士，做过翰林院检讨、四川广东乡试考官、内阁学士，走的是科举正途。康熙四十八年受任四川巡抚，由京官转为封疆；康熙五十九年挂平西将军印，指挥岳钟琪等打进西藏，击败策妄阿拉布坦的驻藏军官策凌敦多卜，此后兼理四川陕西总督，西北军政、粮运、番务皆归其节制。雍正即位，召还抚远大将军胤禵，命他管理大将军印务，雍正元年十月正式接任，坐镇西宁。雍正二年，他指挥岳钟琪平定青海罗卜藏丹津，肃清全境；十月奉召进京，赏双眼花翎、四团龙补服、黄带紫辔与金币，宠遇为诸臣之最。雍正三年二月，他的贺疏把「朝乾夕惕」写成「夕惕朝乾」，被指为有意不敬；四月夺大将军与总督，调杭州将军；十月拿捕来京，十二月赐死，定九十二款大罪，子年富被斩，余子十五岁以上戍边。从青海捷报到狱中自裁，前后不到两年。",
