 "lead": "刘墉，山东诸城人，大学士刘统勋之子。底本没有记他的科第与早年履历，只说他官至左都御史，以刚直敢言著称。他的父亲刘统勋也做过左都御史，其后升至东阁大学士，查办过云南总督恒文、巡抚郭一裕、山西布政使蒋洲、西安将军都赉、归化将军保德、江苏布政使苏崇阿、江西巡抚阿思哈等大员，是乾隆朝有名的打老虎能手，与一般专拍苍蝇的御史不同。刘墉承的是这一路家风，却没有把这股劲全用在明处。乾隆四十七年前后，他探知和珅将先期派人赴山东，授意巡抚国泰、布政使于易简设法蒙混亏空，便赶紧转告御史钱沣将计就计；后来朝廷派钱沣、和珅、刘墉等会同查办，山东库银的亏空终被揭破。四库开馆时他列名副总裁，书法是标准的翰林体。此后的官职、卒年与谥号，底本同样没有交代。在这一案里，他不曾出面弹劾，也不曾与和珅正面相撞，只是把一句话递到了该听的人耳里；清名保住了，案子也办成了，代价是他始终不像钱沣那样有一个直臣的名目。",
 "points": [
  "转折一：名父之子，承刘统勋查办大员的家风，官至左都御史，以刚直敢言著称。",
  "转折二：探知和珅要派人先赴山东授意蒙混，他不正面相撞，转告钱沣将计就计。",
  "转折三：朝廷派钱沣、和珅、刘墉会同查案，亏空揭破；他列名四库副总裁，此后事迹零落。"
 ],
 "why": [
  {
   "q": "为什么刘墉不与和珅正面相撞，却要绕一步把话递给钱沣？",
   "a": "因为左都御史有言责而无查办之权。他若亲自出章，等于把自己摆到和珅的正面，案子还没查，人先被卷入；而钱沣是御史，风闻奏事本是本职，奏章由他递上去名正言顺。刘墉在后撑住，钱沣在前开口，事情才办得动。更有一层：查亏空的规矩是到省盘库，地方一听风声就能挪银补账，先声张只会让对方动作更快。他要的是案子成，不是名声；名声他本来就有。",
   "basis": {
    "type": "book",
    "text": "《细说清朝》六八 巨蠹和珅"
   }
  },
  {
   "q": "为什么他名声很清，事迹却这样零落？",
   "a": "因为他做的多是暗处的事。山东一案他递了一句话，署名的是钱沣；四库馆里他列名副总裁，校书的是总纂与分纂。他不出头，也就不留痕。底本记他官至左都御史、以刚直敢言著称，此后的官职、卒年与谥号一概未载，可见关于他的材料本就零散。清名是靠人品与书法传下来的，事迹却要有案子、有奏章才留得住。",
   "basis": {
    "type": "book",
    "text": "《细说清朝》六八 巨蠹和珅"
   }
  }
 ],
