    "a": "因为朝廷议和需要一个人担过。英军不从广东正面来攻，却直抵大沽口，说明海防的破口不在广州一隅；但承认这一点，就等于承认整个海防与对外体制都有问题，代价太大。否定林则徐的措置，则只需换一个人、改一套办法。穆彰阿一系又久已不满他的强硬，正好借势。他在回京途中被降旨革职，圣旨里没有一个字提禁烟的是非。",
