    "a": "因为朝廷要用的是他的老练，不是他的主张。道光末年云南汉回械斗，前任督抚办不下来，能压住局面的老臣不多；林则徐在江苏办过河工、在湖广办过禁烟、在广东办过夷务，刑名与边务都有阅历，且清廉不结党，用他不致养出一个新的势力。起用他为云贵总督，是让他去收拾地方，而不是为虎门翻案。所以他能够复起，却始终没有被召回中枢。",
