MR.people["qing:zengguofan"] = {
 "headline": "一个京官，练出了一支军队",
 "lead": "曾国藩，湖南湘乡人，字涤生，道光十八年进士，入翰林，历官至兵部侍郎。他在京十余年，做的是词臣与部务，没有带过一天兵。咸丰二年丁忧回籍，奉命帮办湖南团练，以湘乡勇为基础练成湘军，办水师、造战船，与太平军角逐长江。咸丰四年靖港兵败，愤而投水，被左右救起；此后以安庆为根本，逐步压缩天京。咸丰十年署两江总督，同治三年克复南京，封一等毅勇侯，随即裁撤湘军大半。同治四年奉命剿捻，战事迁延，改由李鸿章接统；七年调直隶总督，九年办天津教案，物议沸腾，复回两江。同治十一年卒于南京，谥文正。他治军以扎硬寨、打死仗为法，用人不循资格；幕府中左宗棠、李鸿章、曾国荃、彭玉麟一时并出，湘军因而成了晚清人才的渊薮。",
 "points": [
  "转折一：丁忧在籍的京官奉命帮办团练，以湘乡勇为底子练成湘军，办水师、造战船，从词臣变成了统帅。",
  "转折二：靖港兵败投水被救，湖口再挫，困顿江西数年；守制未满而奉旨复出，才重新握住兵柄。",
  "转折三：先取安庆再困天京，克城之后自裁湘军大半；天津教案一意敷衍，清望大损，身后仍得谥文正。"
 ],
 "why": [
  {
   "q": "为什么一个从未带过兵的京官，能变成统兵十余万的统帅？",
   "a": "因为他抓住的不是兵权，是办团练的资格。清代团练本由在籍官绅主持，粮饷自筹、人事自选，朝廷给的只是名义；他丁忧在籍，正好合例。选营官用书生，招兵用山乡农夫，兵将同乡同里，命令可以一直贯到哨队，这是绿营做不到的。加上八旗绿营已朽、太平军压境，湖南人自保之心正急，朝廷也只好让这样的人去办。他不是学会了打仗，是把官府办不成的事，用乡里的办法办成了。",
   "basis": {
    "type": "book",
    "text": "《细说清朝》九四 曾国藩"
   }
  }
 ],
 "gap": [
  "曾国藩练勇初期所招各营的准确人数，书中所载简略",
  "湘军水师战船图式的来源，史无明文"
 ],
 "quotes": []
};
