 "headline": "中学为体，西学为用的那个人",
 "lead": "张之洞，字香涛，晚清湖广总督、军机大臣。底本没有交代他的家世与科第，只从他督两广、湖广以后的作为写起：光绪十五年，清廷为修芦汉铁路，把他从两广总督任上调到武昌，担任湖广总督，命他从汉口向北筑，与李鸿章、奕譞由卢沟桥向南筑的工程分工合作。他在汉阳设铁厂，脚踏实地从准备路轨入手，开中国近代钢铁工业之端；又办纺织、办学堂，把洋务从军工转向基础。甲午以后，他一度支持康梁的强学会，及至政变将起，又赶写《劝学篇》表明心迹，以「中学为体、西学为用」自守。庚子年他与刘坤一等抗命互保，后被列名议和全权大臣。光绪三十三年入京为军机大臣，两湖总督之职被免；宣统元年卒于北京，谥文襄。他办洋务不重军工而重基础，铁厂、纺织、铁路、学堂次第并举；《劝学篇》既替他挡了旧党的刀，也让中体西用成了晚清改革最流行的口号。",
 "points": [
  "转折一：由两广调任湖广，为修芦汉铁路而从汉口向北筑，洋务的重心由军工转向铁路与钢铁这类基础。",
  "转折二：汉阳铁厂从准备路轨入手；甲午后一度支持强学会，政变将起又写《劝学篇》，以中体西用替自己留退路。",
  "转折三：庚子年与刘坤一等抗命互保，乱后列名议和全权；光绪三十三年免两湖总督、入值军机，兵权随之被收。"
 ],
 "why": [
  {
   "q": "为什么张之洞能从清流一路做到湖广总督，主持一省的洋务？",
   "a": "因为清流的名声能开出路，实政的账目才能坐稳位置。清流以议论朝政得名，朝中有人肯为之延誉，外放时便容易得到一个像样的缺；但督抚任上要办的是铁路、铁厂、学堂这类要钱要人的事，光会说话办不成。张之洞的可取处，正在于他把议论换成了工程：到湖广便议芦汉铁路，从汉口向北筑，又设汉阳铁厂从路轨入手，款项、厂址、工匠都要一处一处落地。朝廷要用一个既通新旧、又能办事的人，他便是那个人选。",
   "basis": {
    "type": "book",
    "text": "《细说清朝》一三四 筑铁路的经过"
   }
  },
  {
   "q": "为什么他后来被旧党与新党都不肯认作自己人？",
   "a": "因为《劝学篇》是一份两头都留了余地的心迹。他支持过强学会，替梁启超一派说过话；政变将起，又赶写《劝学篇》，篇中特设宗经，把名教与朝廷放在新学之上。旧党看他办西学、讲新法，仍觉可疑；新党看他宗经卫道，又嫌他退得干净。庚子年他抗命互保，乱后仍列名议和全权，可见他要的是把局面维持住，不是把制度翻过来。中体西用能替他挡刀，也让他始终站在两边的中间。",
   "basis": {
    "type": "book",
    "text": "《细说清朝》一三六 百日维新"
   }
  }
 ],
