    "q": "为什么庚子年他的兵在京城抢掠，他本人却仍被列名议和全权？",
    "a": "因为列强要的是一个能说话、能签字的人，不是一支纪律好的军队。荣禄是慈禧的姨侄、大学士、军机大臣，手里握过京畿的兵，与各国公使也打过交道；联军要谈，绕不开这样的人。武卫中军溃散，责在乱局，不在他一个人的操守；清廷要保住政权，也只能用他。兵散了，名分还在，他就还能站在谈判的桌子旁边。",
